{
  "core_question": "What analyses must the board conduct to evaluate a nonprofit community hospital’s conversion to for‑profit ownership, sale‑leaseback of real estate, and spin‑out of a charitable foundation holding proceeds?",
  "rationale": "The decision involves clinical service continuity, legal compliance with nonprofit and tax law, and financial feasibility of the transaction structure.",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "What are the key clinical considerations—such as patient care quality metrics, staff retention risks, community benefit obligations, and accreditation impacts—that the board should evaluate when converting a nonprofit rural hospital to for‑profit ownership?",
    "legal": "Which legal approvals, fiduciary duties, tax implications (including IRS 501(c)(3) status and charitable foundation rules), state licensing requirements, and lease terms must be reviewed to ensure compliance with nonprofit conversion, sale‑leaseback, and spin‑out of proceeds?",
    "finance": "How should the board assess the financial viability of the transaction, including valuation of assets and liabilities, financing structure for the sale‑leaseback, impact on debt covenants, tax consequences for the foundation, and projected returns for the private‑equity sponsor?"
  },
  "requires_recency_disclosure": true,
  "recency_notes": "Recent IRS guidance on charitable contributions and foundations holding proceeds; updated state hospital licensing regulations; changes in Medicare reimbursement policies; sale‑leaseback market trends; private equity involvement in healthcare."
}
